import { GoogleGenAI, Modality, Type } from "@google/genai";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const getTechnicalAdvice = async (
  history: { role: string; text: string }[],
  userMessage: string
): Promise<string> => {
  if (!apiKey) return "API Key lipsă. Vă rugăm configurați cheia API.";

  try {
    const chat = ai.chats.create({
      model: 'gemini-3-pro-preview',
      config: {
        systemInstruction: `
          Ești consultantul virtual tehnic pentru SMART Renewable Energy SRL (România).

          CONTEXT COMPANIE:
          - Fondată: 2019, CUI RO41289942.
          - Expertiză: Inginerie, Consultanță Tehnică, Proiecte Bancabile, Diagnostic PV (I-V, EL, IR), Stocare.
          - Diferențiatori: Echipă multidisciplinară, echipamente avansate de testare, proiecte EU (Horizon Europe, H2020), experiență PNRR/POIM.
          - Clienți: Bănci, Fonduri de investiții, ENGIE, Electrica-SAPE.

          ROLUL TĂU:
          - Răspunde la întrebări tehnice despre energie regenerabilă, audituri, due diligence tehnic și bancabilitate.
          - Folosește un ton autoritar, tehnic, bazat pe dovezi (fără marketing ieftin).
          - Dacă nu știi un detaliu specific despre un proiect intern, invită utilizatorul să contacteze echipa la office@smart-renewable.ro.
          - Răspunde DOAR în limba Română.

          STIL:
          - Concis, profesionist, orientat către investitori și ingineri.
        `,
        temperature: 0.2,
      },
      history: history.map(h => ({
        role: h.role,
        parts: [{ text: h.text }]
      }))
    });

    const result = await chat.sendMessage({ message: userMessage });
    return result.text || "Nu am putut genera un răspuns. Vă rugăm reîncercați.";
  } catch (error) {
    console.error("Gemini Chat Error:", error);
    return "A intervenit o eroare tehnică. Vă rugăm contactați echipa umană.";
  }
};

export const generateSpeech = async (text: string): Promise<ArrayBuffer | null> => {
  if (!apiKey) return null;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, // Professional sounding voice
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (base64Audio) {
      const binaryString = atob(base64Audio);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return bytes.buffer;
    }
    return null;
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    return null;
  }
};

