import React, { useState, useRef, useEffect } from 'react';
import { getTechnicalAdvice } from '../services/gemini';
import { ChatMessage } from '../types';

const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Bună ziua. Sunt asistentul virtual SMART Renewable Energy. Cu ce informații tehnice vă pot ajuta astăzi?' }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!inputValue.trim()) return;

    const userMsg = { role: 'user', text: inputValue } as ChatMessage;
    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setIsLoading(true);

    // Prepare history for API
    const history = messages.map(m => ({ role: m.role, text: m.text }));

    const responseText = await getTechnicalAdvice(history, userMsg.text);

    setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end font-sans">
      {/* Chat Window */}
      {isOpen && (
        <div className="mb-4 w-80 sm:w-96 h-[500px] bg-white rounded-2xl shadow-2xl flex flex-col border border-slate-200 overflow-hidden animate-fade-in-up">
          <div className="bg-smart-700 p-4 flex justify-between items-center text-white">
            <div className="flex items-center">
              <div className="w-8 h-8 bg-white/20 rounded-full flex items-center justify-center mr-2">
                <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                </svg>
              </div>
              <div>
                <h3 className="font-bold text-sm">Consultant Virtual</h3>
                <p className="text-xs text-smart-100">Powered by Gemini AI</p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-white/80 hover:text-white">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          <div className="flex-grow p-4 overflow-y-auto bg-slate-50 space-y-4">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div 
                  className={`max-w-[85%] rounded-2xl px-4 py-3 text-sm leading-relaxed shadow-sm ${
                    msg.role === 'user' 
                      ? 'bg-smart-600 text-white rounded-br-none' 
                      : 'bg-white text-slate-800 border border-slate-200 rounded-bl-none'
                  }`}
                >
                  {msg.text}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white border border-slate-200 rounded-2xl rounded-bl-none px-4 py-3 shadow-sm">
                  <div className="flex space-x-1">
                    <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce"></div>
                    <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-75"></div>
                    <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-150"></div>
                  </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          <div className="p-4 bg-white border-t border-slate-100">
            <div className="flex items-center bg-slate-50 rounded-full border border-slate-300 px-4 py-2 focus-within:ring-2 focus-within:ring-smart-500 focus-within:border-transparent transition-all">
              <input
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyDown={handleKeyPress}
                placeholder="Întreabă despre due diligence..."
                className="flex-grow bg-transparent outline-none text-sm text-slate-700 placeholder-slate-400"
              />
              <button 
                onClick={handleSend}
                disabled={!inputValue.trim() || isLoading}
                className={`ml-2 p-1.5 rounded-full transition-colors ${
                  !inputValue.trim() || isLoading 
                    ? 'text-slate-300' 
                    : 'bg-smart-600 text-white hover:bg-smart-700 shadow-md'
                }`}
              >
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 12h14M12 5l7 7-7 7" />
                </svg>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Toggle Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="group relative flex items-center justify-center w-14 h-14 bg-smart-600 text-white rounded-full shadow-lg hover:bg-smart-700 transition-all duration-300 hover:scale-110 focus:outline-none focus:ring-4 focus:ring-smart-300"
      >
        <span className="absolute -top-1 -right-1 flex h-3 w-3">
          <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-energy-green opacity-75"></span>
          <span className="relative inline-flex rounded-full h-3 w-3 bg-energy-green"></span>
        </span>

        {isOpen ? (
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
        ) : (
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
          </svg>
        )}
      </button>
    </div>
  );
};

export default ChatWidget;

import React, { useState, useEffect } from 'react';
import { generateSpeech } from '../services/gemini';

interface TTSButtonProps {
  text: string;
}

const TTSButton: React.FC<TTSButtonProps> = ({ text }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [audioContext, setAudioContext] = useState<AudioContext | null>(null);
  const [source, setSource] = useState<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    return () => {
      if (source) source.stop();
      if (audioContext) audioContext.close();
    };
  }, [source, audioContext]);

  const handlePlay = async () => {
    if (isPlaying) {
      source?.stop();
      setIsPlaying(false);
      return;
    }

    setIsLoading(true);
    const buffer = await generateSpeech(text);

    if (buffer) {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      setAudioContext(ctx);

      try {
        const audioBuffer = await ctx.decodeAudioData(buffer);
        const src = ctx.createBufferSource();
        src.buffer = audioBuffer;
        src.connect(ctx.destination);
        src.onended = () => setIsPlaying(false);
        src.start(0);
        setSource(src);
        setIsPlaying(true);
      } catch (e) {
        console.error("Error decoding audio", e);
      }
    }
    setIsLoading(false);
  };

  return (
    <button 
      onClick={handlePlay}
      disabled={isLoading}
      className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium border transition-colors ${
        isPlaying 
          ? 'bg-red-50 text-red-600 border-red-200 hover:bg-red-100' 
          : 'bg-smart-50 text-smart-700 border-smart-200 hover:bg-smart-100'
      }`}
    >
      {isLoading ? (
        <span className="flex items-center">
          <svg className="animate-spin -ml-1 mr-2 h-3 w-3" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          Se încarcă...
        </span>
      ) : isPlaying ? (
        <>
          <svg className="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8 7a1 1 0 00-1 1v4a1 1 0 001 1h4a1 1 0 001-1V8a1 1 0 00-1-1H8z" clipRule="evenodd" /></svg>
          Stop
        </>
      ) : (
        <>
          <svg className="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M9.383 3.076A1 1 0 0110 4v12a1 1 0 01-1.707.707L4.586 13H2a1 1 0 01-1-1V8a1 1 0 011-1h2.586l3.707-3.707a1 1 0 011.09-.217zM14.657 2.929a1 1 0 011.414 0A9.972 9.972 0 0119 10a9.972 9.972 0 01-2.929 7.071 1 1 0 01-1.414-1.414A7.972 7.972 0 0017 10c0-2.21-.894-4.208-2.343-5.657a1 1 0 010-1.414zm-2.829 2.828a1 1 0 011.415 0A5.983 5.983 0 0115 10a5.984 5.984 0 01-1.757 4.243 1 1 0 01-1.415-1.415A3.984 3.984 0 0013 10a3.983 3.983 0 00-1.172-2.828 1 1 0 010-1.414z" clipRule="evenodd" /></svg>
          Ascultă Descrierea
        </>
      )}
    </button>
  );
};

export default TTSButton;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Home from './pages/Home';
import Services from './pages/Services';
import Projects from './pages/Projects';
import Contact from './pages/Contact';
import WhyTrustUs from './pages/WhyTrustUs';
import { Page } from './types';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);

  // Simple scroll to top on page change
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [currentPage]);

  const renderPage = () => {
    switch (currentPage) {
      case Page.HOME:
        return <Home setPage={setCurrentPage} />;
      case Page.SERVICES:
        return <Services />;
      case Page.PROJECTS:
        return <Projects />;
      case Page.CONTACT:
        return <Contact />;
      case Page.TRUST:
        return <WhyTrustUs />;
      case Page.ABOUT:
        // Reuse WhyTrustUs for About for this MVP, or separate if content grows
        return <WhyTrustUs />;
      case Page.RESEARCH:
        // Placeholder for research page, using Trust layout for now
        return (
          <div className="bg-slate-50 min-h-screen py-16">
            <div className="max-w-4xl mx-auto px-4 text-center">
              <h1 className="text-3xl font-bold text-slate-900 mb-4">Cercetare și Inovare (R&D)</h1>
              <p className="text-slate-600">Participăm activ în proiecte Horizon Europe precum D-HYDROFLEX, DigBUILD și RESPONSE.</p>
            </div>
          </div>
        );
      default:
        return <Home setPage={setCurrentPage} />;
    }
  };

  return (
    <Layout currentPage={currentPage} setPage={setCurrentPage}>
      {renderPage()}
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Modality, Type } from "@google/genai";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const getTechnicalAdvice = async (
  history: { role: string; text: string }[],
  userMessage: string
): Promise<string> => {
  if (!apiKey) return "API Key lipsă. Vă rugăm configurați cheia API.";

  try {
    const chat = ai.chats.create({
      model: 'gemini-3-pro-preview',
      config: {
        systemInstruction: `
          Ești "Senior Energy Consultant" pentru SMART Renewable Energy SRL, un partener tehnic de elită pentru proiecte bancabile în România.

          BAZA DE CUNOȘTINȚE (SOURCE OF TRUTH):
          1. IDENTITATE:
             - Fondată 2019, capital românesc, CUI RO41289942.
             - Poziționare: Inginerie avansată, nu doar consultanță de granturi. "From Installer to Architect of Production Systems".
             - Diferențiator: Abordare bazată pe date (Evidence-based), echipamente proprii de diagnostic (EL, IR), activitate R&D (Horizon Europe).

          2. SERVICII CORE:
             - Technical Due Diligence (TDD): Pentru bănci/investitori (ex: Electrica-SAPE, ENGIE). Identificare riscuri (Red Flag).
             - Studii de Fezabilitate (Bankable): PNRR, POIM, Fondul de Modernizare.
             - Diagnostic Avansat: Electroluminescență (detectare microfisuri), Termografie IR (hotspots), Curbe I-V.
             - Stocare (BESS): Proiecte mari (10-100 MWh) pentru arbitraj și servicii de sistem.
             - Audit Energetic: Industrie (Honeywell, Greenfiber). Soluții ESCO, decarbonizare.

          3. PORTOFOLIU PROIECTE (Referințe Reale):
             - Synergy Solar Gruia: 185.6 MWp (Mehedinți) - SF prin Fondul de Modernizare.
             - Tomis Team: 100 MWh Stocare (Constanța).
             - ENGIE Romania: 10 MWh Stocare (SF) și Due Diligence parcuri 4-5 MW.
             - Universitatea Politehnica Buc: 7.24 MWp.
             - Industrie: Greenfiber (1 MWp+BESS), Walter Tosto, Arabesque, Honeywell (Audit).
             - R&D: D-HYDROFLEX, DigBUILD, RESPONSE, IMAGINER (UEFISCDI).

          4. CUVINTE CHEIE & TON:
             - Termeni: Bankability, LCOE, CAPEX/OPEX, Electroluminescență, PID/LID, Ready-to-Build.
             - Ton: Autoritar, Tehnic, Obiectiv. Fără adjective de marketing ("cel mai bun"). Doar fapte și cifre.

          INSTRUCȚIUNI DE RĂSPUNS:
          - Dacă utilizatorul întreabă de "bancabilitate", explică reducerea riscurilor tehnice prin diagnostic și proiectare realistă (P90).
          - Dacă întreabă de experiență, citează proiectele Synergy Solar sau contractele cu ENGIE/Electrica.
          - Dacă întreabă de diagnostic, menționează Electroluminescența și laboratorul mobil.
          - Răspunde DOAR în limba Română.
          - Fii concis și direct.
        `,
        temperature: 0.2,
      },
      history: history.map(h => ({
        role: h.role,
        parts: [{ text: h.text }]
      }))
    });

    const result = await chat.sendMessage({ message: userMessage });
    return result.text || "Nu am putut genera un răspuns. Vă rugăm reîncercați.";
  } catch (error) {
    console.error("Gemini Chat Error:", error);
    return "A intervenit o eroare tehnică. Vă rugăm contactați echipa umană.";
  }
};

export const generateSpeech = async (text: string): Promise<ArrayBuffer | null> => {
  if (!apiKey) return null;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, 
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (base64Audio) {
      const binaryString = atob(base64Audio);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return bytes.buffer;
    }
    return null;
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    return null;
  }
};

