const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);

  // Simple scroll to top on page change
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [currentPage]);

  const renderPage = () => {
    switch (currentPage) {
      case Page.HOME:
        return <Home setPage={setCurrentPage} />;
      case Page.SERVICES:
        return <Services />;
      case Page.PROJECTS:
        return <Projects />;
      case Page.CONTACT:
        return <Contact />;
      case Page.TRUST:
        return <WhyTrustUs />;
      case Page.ABOUT:
        return <WhyTrustUs />;
      case Page.RESEARCH:
        return <Research />;
      default:
        return <Home setPage={setCurrentPage} />;
    }
  };

  return (
    <Layout currentPage={currentPage} setPage={setCurrentPage}>
      {renderPage()}
    </Layout>
  );
};

