import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Home from './pages/Home';
import Services from './pages/Services';
import Projects from './pages/Projects';
import Contact from './pages/Contact';
import WhyTrustUs from './pages/WhyTrustUs';
import About from './pages/About';
import Research from './pages/Research';
import { Page } from './types';

const App: React.FC = () => {
  // Initialize state from URL param if present, otherwise default to HOME
  const getInitialPage = (): Page => {
    const params = new URLSearchParams(window.location.search);
    const pageParam = params.get('page');
    if (pageParam && Object.values(Page).includes(pageParam as Page)) {
      return pageParam as Page;
    }
    return Page.HOME;
  };

  const [currentPage, setCurrentPage] = useState<Page>(getInitialPage);

  // Sync URL with State
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get('page') !== currentPage) {
      if (currentPage === Page.HOME) {
        window.history.pushState({}, '', window.location.pathname);
      } else {
        params.set('page', currentPage);
        window.history.pushState({}, '', `${window.location.pathname}?${params.toString()}`);
      }
    }
    window.scrollTo(0, 0);
  }, [currentPage]);

  // Handle Browser Back/Forward buttons
  useEffect(() => {
    const handlePopState = () => {
      setCurrentPage(getInitialPage());
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const renderPage = () => {
    switch (currentPage) {
      case Page.HOME:
        return <Home setPage={setCurrentPage} />;
      case Page.SERVICES:
        return <Services />;
      case Page.PROJECTS:
        return <Projects />;
      case Page.CONTACT:
        return <Contact />;
      case Page.TRUST:
        return <WhyTrustUs />;
      case Page.ABOUT:
        return <About />;
      case Page.RESEARCH:
        return <Research />;
      default:
        return <Home setPage={setCurrentPage} />;
    }
  };

  return (
    <Layout currentPage={currentPage} setPage={setCurrentPage}>
      {renderPage()}
    </Layout>
  );
};

export default App;

